    //    b
    //  d e f
    //    h
    let b = fsrRcasLoad(sp + vec2<f32>(0.0, -1.0)).rgb;
    let d = fsrRcasLoad(sp + vec2<f32>(-1.0, 0.0)).rgb;
    let e = fsrRcasLoad(sp).rgb;
    let f = fsrRcasLoad(sp + vec2<f32>(1.0, 0.0)).rgb;
    let h = fsrRcasLoad(sp + vec2<f32>(0.0, 1.0)).rgb;

